def _attn_prune_parse_layers(
    value: object | None = None,
    env_name: str = "QWEN3VL_ATTN_PRUNE_LAYERS",
) -> set[int]:
    if value is None:
        value = os.getenv(env_name, "")
    if isinstance(value, (list, tuple, set)):
        out = set()
        for item in value:
            try:
                out.add(int(item))
            except Exception:
                continue
        return out
    text = str(value or "").strip()
    if not text:
        return set()
    out = set()
    for item in text.split(","):
        item = item.strip()
        if not item:
            continue
        try:
            out.add(int(item))
        except Exception:
            continue
    return out


